    rank: [["Weight domains", "Natural disaster .30 · technical disaster .25 · crime .15 · traffic .10 · street retail .10 · begging .10"], ["Score communities", "Weighted domain intensities accumulate into each community's cumulative score"], ["Rank + join blocks", "Communities ranked; the ranking joins the segmentation's irregular blocks"], ["Browse", "Map solo or bivariate vs building density; sortable top-30 table"]],
    priority: [["Score severity", "Cumulative rank + domain sub-scores per irregular block"], ["Weigh feasibility (proposed joins)", "Tenure status, budget window, agency capacity, land value"], ["Classify", "P1 act now · P2 program · P3 monitor · P4 watch"], ["Select areas", "Priority AI suggests P1/P2; the urban governor decides; the rest keep their trend line"]],
    participate: [["Read the metro policy toolkit", "Each metro policy toolkit sets a participation floor and ceiling"], ["Pick the pool", "Classes 3–5 operable; 1–2 context; 6 monitored risk"], ["Match context", "Thai channels (CODI, Traffy, youth councils) where they exist"], ["Assemble package", "Techniques per area, with failure modes checked"]],
