    design: [["Strategy map", "Metro policy toolkit actions placed: fire lanes, plots, common-use, markets"], ["Component cards", "Each location tied to an image card with its description"], ["Participation gate", "Selected techniques run before works are fixed"], ["Approve + program", "Approved strategy enters the intervention program"]],
